import {fixtures} from './data.js';
import {analyze,runDate,runExperiment,rankFor,validateSources,VERSION} from './engine.js';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageError=false,custom=[];try{custom=JSON.parse(localStorage.getItem('between.people.v1')||'[]');if(!Array.isArray(custom))custom=[];}catch{storageError=true;}
let people=fixtures.map(analyze);for(const p of custom){try{if(!people.some(x=>x.id===p.id))people.push(analyze(p));}catch{storageError=true;}}
let dates=runExperiment(people),city='All cities',query='',sort='curated',currentDate=null,turnCount=0,timer=null,selectedRank=people[0].id;
const palettes=['#d9ddc9','#ded6e7','#e5c6ad','#ccdcd8','#e2d8c1','#d7d5c9'];
function portrait(p){const n=p.index??25,bg=palettes[n%6],skin=['#bd815d','#e5b08a','#754b37','#c9926c','#98613f'][n%5],shirt=['#596650','#8d6356','#66627d','#b1a16c','#496e72'][n%5],hair=['#302d28','#51382e','#242b29','#805a3b'][n%4];return `<svg viewBox="0 0 220 240" role="img" aria-label="Illustrated fictional portrait of ${esc(p.name)}"><path d="M30 240v-39q0-40 55-49h50q55 9 55 49v39" fill="${shirt}"/><path d="M90 140v28q20 24 40 0v-28" fill="${skin}"/><ellipse cx="110" cy="100" rx="47" ry="59" fill="${skin}"/><path d="M64 99Q52 30 108 29q60 0 52 77l-12-39q-32 14-64-3z" fill="${hair}"/>${n%3===0?`<path d="M66 71Q45 130 57 163l28-10-8-61M152 69q24 42 9 93l-26-12 12-52" fill="${hair}"/>`:''}<path d="M84 100h13m27 0h13" stroke="#332c25" stroke-width="3" stroke-linecap="round"/><path d="m111 104-4 17h8" stroke="#00000025" stroke-width="2" fill="none"/><path d="M99 134q11 7 22-1" stroke="#613d32" stroke-width="2.5" fill="none" stroke-linecap="round"/>${n%4===1?'<g stroke="#353f39" stroke-width="2" fill="none"><rect x="76" y="90" width="28" height="22" rx="8"/><rect x="117" y="90" width="28" height="22" rx="8"/><path d="M104 97h13"/></g>':''}<path d="m82 174 28 20 28-20" stroke="#ffffff55" stroke-width="2" fill="none"/><path d="M110 195v45" stroke="#00000012" fill="none"/></svg>`;}
const mini=p=>`<span class="mini-avatar" style="--portrait-bg:${palettes[(p.index??25)%6]}">${portrait(p)}</span>`;
const tags=arr=>arr.map(h=>`<span class="tag">${esc(h)}</span>`).join('');
const options=(selected)=>people.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function closeModal(){modal.close();}
function showModal(title,content){$('#modal-content').innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${content}`;modal.showModal();}
function navigate(hash){if(location.hash===hash)render();else location.hash=hash;}
function card(p){return `<article class="person-card"><div class="portrait-scene" style="--portrait-bg:${palettes[(p.index??25)%6]}"><span class="number">NO. ${String(p.index+1).padStart(2,'0')}</span>${portrait(p)}<span class="live">Agent ready</span></div><div class="card-body"><div class="person-heading"><h3>${esc(p.name)} <span class="age">${p.age}</span></h3><span class="place">${esc(p.city)}</span></div><p class="role">${esc(p.role)}</p><div class="tags">${tags(p.hobbies)}</div><p class="card-quote">“${esc(p.needs)}”</p><div class="card-footer"><div class="source-mini" aria-label="Two fictional sources"><span>in</span><span>◎</span></div><button class="profile-link" data-action="profile" data-id="${p.id}">Meet ${esc(p.name.split(' ')[0])}’s agent <span aria-hidden="true">↗</span></button></div></div></article>`;}
function peoplePage(){main.innerHTML=`<section class="hero"><div><span class="pill"><span class="dot"></span> The dating lab · fictional edition</span><h1>A little less swiping.<br>A little more <em>connection.</em></h1><p>Your interests. Your quirks. Your kind of Sunday.<br>Meet the agents getting to know each other, on your behalf.</p><div class="hero-actions"><a class="button primary" href="#profile/maya-chen">Meet the people <span>↗</span></a><a class="text-button" href="#dates">Watch a date <span>→</span></a><span class="hero-note">25 people. A world of possibilities.</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit">${portrait(people[0])}</div><div class="orbit second">${portrait(people[1])}</div><div class="connection-note"><span class="spark">✳</span><span><strong>Good chemistry starts with a conversation.</strong>Two perspectives. Something in common.</span></div></div></section><section class="workspace"><div class="stats"><div class="stat"><strong>${people.length}</strong><span>fictional people<br>with their own stories</span></div><div class="stat"><strong>${people.length}</strong><span>personal agents<br>ready to connect</span></div><div class="stat"><strong>${dates.length}</strong><span>simulated dates<br>every pairing explored</span></div><div class="stat"><strong>2</strong><span>source profiles<br>behind every agent</span></div></div><div class="section-head"><div><h2 class="section-title">Everyone has a story.</h2><div class="section-sub">Start with a person. See what their agent sees.</div></div><div class="toolbar"><label class="search"><span class="sr-only" hidden>Search people</span><input id="search" type="search" aria-label="Search people, interests, or careers" placeholder="Find a person or interest" value="${esc(query)}"></label><select id="sort" aria-label="Sort people"><option value="curated">Curated order</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option></select></div></div><div class="filters">${['All cities','Brooklyn','London','Barcelona','Amsterdam'].map(c=>`<button class="filter ${city===c?'active':''}" data-action="city" data-city="${c}" aria-pressed="${city===c}">${c}</button>`).join('')}<span class="count" id="people-count"></span></div><div class="people-grid" id="people-grid"></div><div class="demo-banner"><span>Entirely fictional. Every source, every person, every date.</span><button class="text-button" style="color:inherit" data-action="method">Inside the experiment ↗</button></div></section>`;renderCards();$('#search').addEventListener('input',e=>{query=e.target.value;renderCards();});$('#sort').addEventListener('change',e=>{sort=e.target.value;renderCards();});}
function renderCards(){let list=people.filter(p=>(city==='All cities'||p.city===city)&&`${p.name} ${p.role} ${p.hobbies.join(' ')} ${p.values.join(' ')}`.toLowerCase().includes(query.toLowerCase()));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#people-count').textContent=`${list.length} people to get to know`;$('#people-grid').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h2>No people found, yet.</h2><p>Try a different interest or city.</p><button class="button" data-action="reset-search">Clear filters</button></div>`;}
function profilePage(id){const p=people.find(p=>p.id===id);if(!p){main.innerHTML='<div class="workspace empty"><h1>Person not found</h1><a href="#people">Back to everyone</a></div>';return;}main.innerHTML=`<section class="workspace"><div class="page-top"><a class="back" href="#people">← Back to the people</a></div><div class="profile-layout"><aside class="profile-aside"><div class="portrait-scene" style="--portrait-bg:${palettes[p.index%6]}">${portrait(p)}</div><h1>${esc(p.name)}<span class="muted">, ${p.age}</span></h1><div class="role">${esc(p.role)} · ${esc(p.city)}</div><span class="pill">Fictional person · agent ready</span><div class="source-buttons"><button class="button small" data-action="source" data-id="${p.id}" data-source="0">in &nbsp; LinkedIn fixture ↗</button><button class="button small" data-action="source" data-id="${p.id}" data-source="1">◎ &nbsp; Instagram fixture ↗</button></div><button class="button primary" data-action="date-person" data-id="${p.id}">Watch my agent date ↗</button><button class="text-button" style="display:block" data-action="rank-person" data-id="${p.id}">See my ranked connections →</button></aside><div class="profile-main"><div class="eyebrow">The person behind the agent</div><h2>“${esc(p.caption)}”</h2><p class="muted">${esc(p.about)}</p><div class="trait-grid"><div class="trait"><span>Looking for</span><strong>${p.intent==='committed'?'A lasting connection':p.intent==='exploring'?'Room to explore':'Not specified'}</strong></div><div class="trait"><span>Everyday rhythm</span><strong>${esc(p.pace)}</strong></div><div class="trait"><span>Social energy</span><strong>${esc(p.social)}</strong></div></div><h2>What matters to ${esc(p.name.split(' ')[0])}.</h2><blockquote class="intro-quote">${esc(p.needs)}</blockquote><div class="eyebrow">Hobbies & interests</div><div class="tags" style="margin:12px 0 22px">${tags(p.hobbies)}</div><div class="eyebrow">Values they named</div><div class="tags" style="margin:12px 0 22px">${tags(p.values)}</div><h2>No guesswork. Here’s the evidence.</h2><p class="section-sub">Extracted statements from the two fictional sources. Unstated traits remain unknown.</p>${p.evidence.map(e=>`<div class="evidence-row"><strong>${esc(e.key)}</strong><p>${esc(e.quote)}<br><small>${e.confidence}</small></p><button data-action="source" data-id="${p.id}" data-source="${e.source}">${e.source?'Instagram':'LinkedIn'} ↗</button></div>`).join('')}<div class="notice">The agent can represent stated interests and preferences. It cannot know real chemistry. Career and hobbies never substitute for a stated relationship intention.</div></div></div></section>`;}
function datesPage(aid=people[0].id,bid=people[1].id){if(aid===bid)bid=people.find(p=>p.id!==aid).id;main.innerHTML=`<section class="workspace"><div class="page-top"><span class="eyebrow">02 / The conversation</span><h1>A first date. Two points of view.</h1><p>Watch two agents listen, ask, and work through the little differences. Open any turn to see the evidence behind it.</p></div><div class="split"><aside class="panel"><h2>Set the scene.</h2><div class="form-field"><label for="date-a">First agent</label><select id="date-a">${options(aid)}</select></div><div class="form-field"><label for="date-b">Second agent</label><select id="date-b">${options(bid)}</select></div><div class="form-field"><label for="venue">The setting</label><select id="venue"><option value="coffee">A neighborhood café</option><option value="walk">The botanical garden</option><option value="gallery">An independent gallery</option></select></div><button class="button primary" style="width:100%" data-action="start-date">Start a date ↗</button><div class="notice">Each agent knows its person’s two sources and responds to the other agent’s stated preferences.</div><p class="section-sub">Inspectable rule-based agents · 6 conversational turns · no language-model API required</p><button class="text-button" data-action="run-all">Re-run all ${people.length*(people.length-1)/2} pairings →</button></aside><div id="date-stage"></div></div><div class="section-head"><div><h2 class="section-title">Every conversation leaves a trace.</h2><p class="section-sub">${dates.length} pairwise dates are already available. Explore them from anyone’s connections.</p></div><a class="button" href="#rankings">Explore connections →</a></div></section>`;currentDate=runDate(people.find(p=>p.id===aid)||people[0],people.find(p=>p.id===bid)||people[1]);turnCount=0;renderStage();}
function turnHTML(t){const p=people.find(p=>p.id===t.speaker);return `<article class="turn">${mini(p)}<div class="bubble"><div class="speaker"><span>${esc(t.name.split(' ')[0])}’s agent</span><span class="phase">${esc(t.phase)}</span></div><p>${esc(t.text)}</p><details><summary>Why my agent said this</summary><p>${esc(t.decision)}</p><button class="text-button" data-action="source" data-id="${p.id}" data-source="${t.source}">Read the ${t.source?'Instagram':'LinkedIn'} evidence ↗</button></details></div></article>`;}
function dimensionsHTML(d){return d.dimensions.map(x=>`<div class="dimension"><span>${x.key} <span class="muted">(${x.weight}%)</span></span><div class="meter"><i style="width:${(x.value??0)*100}%"></i></div><span>${x.value===null?'?':Math.round(x.value*100)+'%'}</span></div>`).join('');}
function renderStage(){const d=currentDate,a=people.find(p=>p.id===d.a),b=people.find(p=>p.id===d.b),done=turnCount===6;$('#date-stage').innerHTML=`<div class="date-stage"><div class="stage-top"><div class="date-pair">${mini(a)}${mini(b)}<div><h2>${esc(a.name.split(' ')[0])} & ${esc(b.name.split(' ')[0])}</h2><p>${esc(d.location)}</p></div></div><span class="stage-status">${done?'Date complete':timer?'● In conversation':'Ready when you are'}</span></div><div class="transcript" id="transcript" aria-live="polite">${turnCount?d.transcript.slice(0,turnCount).map(turnHTML).join(''):'<div class="empty"><span class="spark">✳</span><h2>Let’s see where this goes.</h2><p>Start the date to watch the conversation unfold,<br>or reveal it one turn at a time.</p></div>'}</div><div class="stage-bottom"><span>${turnCount} / 6 turns · ${esc(d.venue)}</span><div><button class="button small" data-action="pause-date" ${!timer?'disabled':''}>Pause</button> <button class="button small" data-action="next-turn" ${done?'disabled':''}>Next turn →</button> <button class="button small" data-action="reveal-date" ${done?'disabled':''}>Read all</button></div></div>${done?`<div class="date-result"><span class="big-score">${d.score}<small style="font:12px 'DM Sans'"> /100</small></span><span class="eyebrow">After the date</span><h3>${d.verdict}</h3><p>${d.interests.length?'Common ground: '+esc(d.interests.join(', '))+'.':'No shared interests explicitly stated.'} ${d.friction.length?esc(d.friction.join('. '))+'.':'No conflicts found in the stated preferences.'}</p>${dimensionsHTML(d)}<p>Evidence coverage ${d.confidence}%. This is a heuristic fit score, not a probability of relationship success.</p><button class="button small" data-action="rank-person" data-id="${a.id}">See ${esc(a.name.split(' ')[0])}’s connections →</button></div>`:''}</div>`;const t=$('#transcript');if(turnCount)t.scrollTop=t.scrollHeight;}
function stopTimer(){clearInterval(timer);timer=null;}
function startDate(){const a=$('#date-a').value,b=$('#date-b').value;if(a===b){toast('Choose two different people for the date.');return;}stopTimer();currentDate=runDate(people.find(p=>p.id===a),people.find(p=>p.id===b),$('#venue').value);turnCount=1;timer=setInterval(()=>{turnCount++;if(turnCount>=6)stopTimer();renderStage();},4500);renderStage();}
function rankingsPage(id=selectedRank){selectedRank=people.some(p=>p.id===id)?id:people[0].id;const p=people.find(p=>p.id===selectedRank),ranked=rankFor(p.id,people,dates);main.innerHTML=`<section class="workspace"><div class="page-top"><span class="eyebrow">03 / The possibilities</span><h1>Some connections feel closer.</h1><p>A ranking from ${esc(p.name.split(' ')[0])}’s perspective, after ${ranked.length} simulated dates. Shared values matter. Different intentions matter, too.</p></div><div class="split"><aside class="panel"><h2>Whose connections?</h2><label for="rank-person">Choose a person</label><select id="rank-person" style="width:100%;margin:8px 0 20px">${options(p.id)}</select><div class="date-pair">${mini(p)}<div><strong>${esc(p.name)}</strong><p>${esc(p.city)}</p></div></div><div class="summary-stats"><div><strong>${ranked.length}</strong><span>dates explored</span></div><div><strong>${ranked.filter(r=>r.score>=70).length}</strong><span>scores above 70</span></div></div><p class="section-sub">A fit score weighs values, interests, intention, everyday rhythm, social energy, and the date negotiation.</p><div class="notice">An intention mismatch caps a score at 49. Missing information earns no points. Distance is flagged, not assumed away.</div><button class="text-button" data-action="profile" data-id="${p.id}">Back to the profile →</button><button class="text-button" style="display:block" data-action="export">Download all results ↓</button></aside><div><div class="section-head" style="margin-top:0"><h2 class="section-title">A little more in common.</h2><span class="pill">${ranked.length} connections</span></div>${ranked.map((r,i)=>`<article class="ranking-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span>${mini(r.person)}<div><h3><a href="#profile/${r.person.id}" style="text-decoration:none">${esc(r.person.name)}</a></h3><p>${esc(r.date.verdict)} · ${esc(r.person.city)}</p><div class="tags">${tags(r.date.interests.slice(0,3))}</div></div><div class="rank-score">${r.score}<small> /100</small></div><button class="button small" data-action="rank-detail" data-id="${r.person.id}">Why this fit ↗</button></article><div id="detail-${r.person.id}" hidden class="rank-detail">${dimensionsHTML(r.date)}<p class="section-sub">${esc(r.date.friction.join('. ')||'No explicit preference conflicts. Real chemistry is unknown.')}.</p><p class="section-sub">Perspective adjustment: 90% pair score + 10% coverage of ${esc(p.name.split(' ')[0])}’s interests. Evidence coverage: ${r.date.confidence}%.</p><button class="button small" data-action="replay" data-a="${p.id}" data-b="${r.person.id}">Watch their date →</button></div>`).join('')}</div></div></section>`;$('#rank-person').addEventListener('change',e=>navigate('#rankings/'+e.target.value));}
function sourceModal(id,index){const p=people.find(p=>p.id===id),s=p.sources[index];showModal(`${index?'Instagram':'LinkedIn'} source`, `<p class="modal-intro">Authored fictional fixture · ${esc(p.name)} · ${index?'Public profile':'Public professional profile'}</p><p class="source-url">${esc(s.url)}</p><pre class="source-document">${esc(s.text)}</pre><div class="notice">This .example address identifies a local fixture. It is not a real social account, and no external scraping is claimed.</div>`);}
function addModal(){const p=fixtures[0];showModal('A person. Two sources.',`<p class="modal-intro">Paste a pair of demo links to read an existing fictional person, or provide two source documents for a new fictional character.</p><form id="add-form"><div class="form-field"><label for="linkedin-url">LinkedIn fixture URL</label><input id="linkedin-url" type="url" required placeholder="https://linkedin.example/in/maya-chen"></div><div class="form-field"><label for="instagram-url">Public Instagram fixture URL</label><input id="instagram-url" type="url" required placeholder="https://instagram.example/maya-chen"></div><button type="button" class="text-button" data-action="sample-links">Use Maya’s demo links ↗</button><details id="custom-sources"><summary>Create a new fictional character</summary><p class="section-sub">Use the labeled format below. The parser reads explicit statements; it does not infer unstated traits. Give both URLs a unique fictional handle.</p><div class="modal-grid"><div class="form-field"><label for="linkedin-text">LinkedIn document</label><textarea id="linkedin-text" maxlength="6000" placeholder="Name: Alex Rivers&#10;Age: 28&#10;City: London&#10;Role: Designer&#10;About: Designing public spaces.&#10;Values: curiosity, kindness"></textarea></div><div class="form-field"><label for="instagram-text">Instagram document</label><textarea id="instagram-text" maxlength="6000" placeholder="Bio: Weekend baker.&#10;Interests: baking, hiking&#10;Pace: steady&#10;Social energy: quiet&#10;Looking for: committed&#10;Needs: Time together and independence."></textarea></div></div><p class="section-sub">Pace: steady / flexible / spontaneous. Social energy: quiet / balanced / social. Looking for: committed / exploring. Other or missing values remain unknown.</p></details><label class="check-label"><input type="checkbox" id="fictional-check" required> These profiles are fictional and the Instagram fixture is public.</label><div id="form-error" role="alert"></div><button type="submit" class="button primary">Read sources & build agent →</button></form>`);$('#add-form').addEventListener('submit',submitPerson);}
async function submitPerson(e){e.preventDefault();const li=$('#linkedin-url').value.trim(),ig=$('#instagram-url').value.trim(),lt=$('#linkedin-text').value.trim(),it=$('#instagram-text').value.trim();let person;try{validateSources(li,ig);const known=people.find(p=>p.sources[0].url===li&&p.sources[1].url===ig);if(known&&!lt&&!it){person=known;}else{if(!lt||!it)throw Error('No matching fixture pair. Use Maya’s demo links, or supply both fictional source documents.');if(people.some(p=>p.sources.some(s=>s.url===li||s.url===ig)))throw Error('Those fixture URLs already belong to a person. Choose unique fictional URLs.');person=analyze({id:'custom-'+crypto.randomUUID(),index:people.length,fictional:true,sources:[{kind:'linkedin',url:li,text:lt},{kind:'instagram',url:ig,text:it,public:true}]});} }catch(err){$('#form-error').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;return;}$('#modal-content').innerHTML=`<div class="modal-top"><h2>Getting to know ${esc(person.name.split(' ')[0])}.</h2></div><p id="analysis-stage" role="status">Reading the LinkedIn fixture…</p><div class="progress"><i id="analysis-progress" style="width:25%"></i></div><p class="section-sub">Two sources. Explicit statements. Traceable evidence.</p>`;const stage=$('#analysis-stage'),progress=$('#analysis-progress');await new Promise(r=>setTimeout(r,450));stage.textContent='Reading the public Instagram fixture…';progress.style.width='55%';await new Promise(r=>setTimeout(r,450));stage.textContent='Extracting preferences and attaching source evidence…';progress.style.width='85%';await new Promise(r=>setTimeout(r,400));if(!people.some(p=>p.id===person.id)){people.push(person);dates=runExperiment(people);try{localStorage.setItem('between.people.v1',JSON.stringify(people.filter(p=>p.id.startsWith('custom-'))));}catch{storageError=true;toast('Added for this session. Browser storage is unavailable; export to keep a copy.');}}closeModal();navigate('#profile/'+person.id);}
function method(){showModal('A little transparency.',`<p class="modal-intro">Between is a working fictional dating laboratory. It is not a real matchmaking service.</p><div class="method-grid"><section><h3>01. Read the person</h3><p>Exactly two authored documents per character: a LinkedIn fixture and a public Instagram fixture. The parser extracts labeled statements and retains the original lines. It never infers private needs from a job title.</p></section><section><h3>02. Let agents meet</h3><p>A stateful, rule-based harness runs six turns: discover, respond, negotiate, resolve, clarify intention, and decide. Each reply branches on the other agent’s profile and preferences. Every branch is visible in the source code.</p></section><section><h3>03. Compare perspectives</h3><p>Values 25%, interests 20%, intention 25%, rhythm 10%, energy 10%, negotiation 10%. A personal adjustment weights how much of the person’s interests the other shares. Intention conflict caps the score at 49.</p></section><section><h3>04. Keep the uncertainty</h3><p>Missing fields stay unknown and receive zero points. Different cities are flagged. Scores are heuristics, not predictions. No external social accounts are scraped, and no language model is used in this edition.</p></section></div><div class="notice">Your added fictional profiles stay in this browser. Export the experiment to save all sources, analyses, transcripts, and rankings. The 25-person example is available on every visit.</div><p class="section-sub">Harness ${VERSION} · ${people.length} people · ${dates.length} dates</p>`);}
function exportAll(){const payload={version:VERSION,fictional:true,exportedAt:new Date().toISOString(),people,dates,rankings:Object.fromEntries(people.map(p=>[p.id,rankFor(p.id,people,dates).map(r=>({person:r.person.id,score:r.score,date:r.date.id}))]))};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='between-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported profiles, sources, dates, and rankings.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;switch(action){case'close':closeModal();break;case'add':addModal();break;case'method':method();break;case'export':exportAll();break;case'profile':navigate('#profile/'+id);break;case'city':city=b.dataset.city;peoplePage();break;case'reset-search':city='All cities';query='';peoplePage();break;case'source':sourceModal(id,Number(b.dataset.source));break;case'date-person':navigate('#dates/'+id+'/'+people.find(p=>p.id!==id).id);break;case'rank-person':navigate('#rankings/'+id);break;case'start-date':startDate();break;case'pause-date':stopTimer();renderStage();break;case'next-turn':stopTimer();turnCount=Math.min(6,turnCount+1);renderStage();break;case'reveal-date':stopTimer();turnCount=6;renderStage();break;case'rank-detail':{const d=$('#detail-'+id);d.hidden=!d.hidden;b.setAttribute('aria-expanded',String(!d.hidden));break;}case'replay':navigate('#dates/'+b.dataset.a+'/'+b.dataset.b);break;case'run-all':dates=runExperiment(people);toast(`Completed ${dates.length} pairwise dates. All rankings refreshed.`);break;case'sample-links':$('#linkedin-url').value=fixtures[0].sources[0].url;$('#instagram-url').value=fixtures[0].sources[1].url;break;}});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});
function render(){stopTimer();const [route='people',id,bid]=location.hash.slice(1).split('/');document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='profile'?'people':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route==='profile')profilePage(id);else if(route==='dates'){const safeA=people.find(p=>p.id===id)?.id||people[0].id;const safeB=people.find(p=>p.id===bid&&p.id!==safeA)?.id||people.find(p=>p.id!==safeA).id;datesPage(safeA,safeB);}else if(route==='rankings')rankingsPage(id);else peoplePage();window.scrollTo(0,0);}
window.addEventListener('hashchange',render);render();if(storageError)toast('Some saved data could not be read. The original 25-person demo is ready.');
